def normalize(data: list) -> list:
    result = []
    for x in data:
        if isinstance(x, (int, float)):
            result.append(x * 2)
        elif isinstance(x, str):
            try:
                result.append(float(x) * 2)
            except (ValueError, TypeError):
                result.append(0)
        else:
            result.append(0)
    return result

def aggregate(data: list) -> dict:
    if not data:
        return {"count": 0, "total": 0}
    # 统一将数据转为数值类型再求和，避免类型不匹配
    numeric = []
    for x in data:
        if isinstance(x, (int, float)):
            numeric.append(x)
        else:
            try:
                numeric.append(float(x))
            except (ValueError, TypeError):
                pass
    total = sum(numeric)
    # 当所有数值均为整型时保持整型，否则保留浮点精度
    if all(isinstance(v, int) for v in numeric):
        total = int(total)
    return {"count": len(data), "total": total}

def report(data: list) -> str:
    normalized = normalize(data)
    stats = aggregate(normalized)
    # 若 total 为浮点但为整数形式，则格式化时去掉 .0
    total_val = stats['total']
    if isinstance(total_val, float) and total_val.is_integer():
        total_val = int(total_val)
    return 'count={0} total={1}'.format(stats['count'], total_val)
